"""Authorized offline frozen-summary rebuild; never recompute raw attention."""
from .cached import *
from ..e29_local_reader.core import bundle_for,files,load_phi,LocalReader,E29,OUT,Summary,contributions,summary_output,page_features,route,gains,checkpoint,E27
from ..e28_local_response.run import digest

@torch.no_grad()
def capture(seed,split):
 torch.set_num_threads(2);dest=DEST/f'{split}_s{seed}';dest.mkdir(parents=True,exist_ok=True);assert not (dest/'capture_complete.json').exists();bundle=bundle_for('C',seed);phi=load_phi(seed);reader=LocalReader().cuda().eval();reader.load_state_dict(torch.load(E29/f's{seed}/selected.pt',map_location='cuda',weights_only=False)['model']);basis=torch.load(OUT/'fit.pt',weights_only=True)['B'].cuda().double();qs=torch.linspace(0,63,16,device='cuda').round().long();paths=files(split);groups=collections.defaultdict(list);sources=[];pairs=[];pages=[];eventrows=[];identities=collections.defaultdict(list);numericids=collections.defaultdict(set);start=time.time();metas=[];maxreplay=0.;frozen={n:x.cpu().clone() for n,x in bundle.layers.state_dict().items()}
 for i,path in enumerate(paths):
  ev=torch.load(path,map_location='cpu',weights_only=True);assert ev['split']==split;groups[path.parent/ev['kv_file']].append((i,path,ev))
 old=json.loads((E38/f'B_s{seed}/action_margin_attribution.json').read_text()) if split=='development' else None;reg=json.loads((E38/f'B_s{seed}/region_attribution.json').read_text()) if split=='development' else None
 for gi,(kvpath,entries) in enumerate(groups.items()):
  kv=torch.load(kvpath,map_location='cpu',weights_only=True);ev=entries[0][2];key=f'l{ev["layer"]}h{ev["head"]}';d=dict(k=kv['k'][None].cuda(),v=kv['v'][None].cuda(),hp=kv['history_pages'],key=key);s=bundle.make(d,'C');parts=[s.keys[0].float().flatten(1),s.mean[0].float(),s.detail[0].float().flatten(1),s.stats[0].float().flatten(1)];scales=torch.stack([p.square().mean(1).sqrt() for p in parts],1);feat=page_features(s);A=phi.page(feat).reshape(-1,8,4).bfloat16().float();coef=reader.page(feat).reshape(-1,5,17).bfloat16().float();P=len(scales);hp=d['hp'];rawhash=[digest(kv['ids'][p],kv['k'][p],kv['v'][p]) for p in range(hp)];sumhash=[digest(*(getattr(s,n)[0,p] for n in ['keys','mean','detail','stats'])) for p in range(P)];cohash=[digest(coef[p]) for p in range(P)];ahash=[digest(A[p]) for p in range(P)];fn=dest/f'summary_{gi:04d}.pt';torch.save(dict(summary={n:getattr(s,n).cpu() for n in ['keys','mean','detail','stats']},scales=scales.cpu(),coef=coef.cpu(),A=A.cpu(),kv_file=str(kvpath.relative_to(OUT)),history_pages=hp,raw_hashes=rawhash,summary_hashes=sumhash,coefficient_hashes=cohash,A_hashes=ahash),fn)
  # Exactly the current normalized input distance, no learned metric, within-event page pairs.
  dd=torch.cdist(feat.double(),feat.double()).square()/712;dd.fill_diagonal_(float('inf'));nn=dd.argmin(1);control=(torch.arange(P,device='cuda')+P//2)%P;f_dist=dd[torch.arange(P,device='cuda'),nn].sqrt();ctrl_dist=dd[torch.arange(P,device='cuda'),control].sqrt();normrms=torch.stack([p.square().mean(1).sqrt() for p in torch.split(feat,[512,128,24,48],dim=1)],1);recovered=1e-4*normrms/(1-normrms);valid=(normrms<1)&(normrms>=0)&(scales>0);relative=torch.where(valid,(recovered-scales).abs()/scales.clamp_min(1e-30),torch.full_like(scales,float('nan')))
  for idx,path,ev in entries:
   q=ev['q'].cuda().float();N=ev['N'].cuda().double();Z=ev['Z'].cuda().double();dense=ev['dense'].cuda().double();logscale=ev['log_scale'].cuda().double();c=contributions(q,s,bundle.layers[key].basis,logscale);lm=c['logzh']-c['A'].log()[:,None];bt=ev['page_logz'].cuda().double()-logscale[:,None]-c['logzh'];ap=summary_output(c,s,bundle.layers[key].basis);rt=(ev['page_output'].cuda().double()-ap)@basis;u=phi.query(q);pre=torch.einsum('qi,pij->qpj',u,A);F=torch.tanh(pre);actual=phi(q,s);assert torch.equal(F.double(),actual[...,1:]);rp,bp=reader(s,actual);localmse=(rp-rt).square().mean(-1);mask,r,a=route(q[qs],s,bundle.layers[key],ev['own']);g=gains(c,N,Z,dense,mask,r,a)
   # Predicted original E29 decision, exact same normalized output score as E30.
   from ..e30_beta_diagnostics.run import local_scores
   cen=(ap-c['o'][:,None])@basis;sc,_=local_scores(rp[qs],bp[qs],lm[qs],cen[qs],mask,r,a,dense.square().sum()/64+1e-12/64);j=int(sc.argmax()) if sc.max()>0 else -1;jo=int(g.argmax()) if g.max()>0 else -1;gain=float(g[j]) if j>=0 else 0.;candidate=torch.zeros(P,dtype=torch.bool,device='cuda');candidate[r]=True;candidate[a]=True;pred=torch.zeros_like(candidate);opt=pred.clone()
   if j>=0:pred[r[j]]=True;pred[a[j]]=True
   if jo>=0:opt[r[jo]]=True;opt[a[jo]]=True
   ep=pred|opt;flags={'all':torch.ones_like(ep),'candidate':candidate,'endpoint_pair':ep,'other_candidate':candidate&~ep,'background':~candidate,'predicted_endpoint':pred,'oracle_endpoint':opt,'harmful_predicted_endpoint':pred&(gain< -1e-12),'positive_predicted_endpoint':pred&(gain>1e-12),'positive_region_attribution_endpoint':ep&(reg[idx]['phi_endpoint']>0) if reg else torch.zeros_like(ep)}
   event=str(path.relative_to(OUT));meta=dict(seed=seed,event=event,split=split,**{k:ev[k] for k in ['trajectory','layer','head','chunk','step','tile']});metas.append(dict(**meta,index=idx,history_pages=hp,summary_file=fn.name,j_pred=j,j_oracle=jo,proposed_gain=gain));err=bp-bt;w=(2*lm).softmax(0)
   if split=='development':
    x=torch.load(E30/f's{seed}/beta_{idx:04d}.pt',map_location='cuda',weights_only=True);assert x['event']==event;assert torch.equal(F.double(),x['F'][...,1:]);assert torch.allclose(bt,x['beta_true'],atol=1e-8,rtol=1e-8);assert torch.equal(bp,x['betas']['Predicted']);assert j==old[idx]['j_pred'] and jo==old[idx]['j_oracle'];maxreplay=max(maxreplay,float((bt-x['beta_true']).abs().max()))
   for role,ix in flags.items():
    if not ix.any():continue
    f=F[:,ix];e=err[:,ix];ww=(2*lm[:,ix]).flatten().softmax(0).reshape_as(e);evrow=dict(**meta,role=role,pages=int(ix.sum()),samples=f.shape[0]*f.shape[1],component_abs_max=float(f.abs().max()),exact_saturated_components=int((f.abs()==1).sum()),exact_any_samples=int((f.abs()==1).any(-1).sum()),exact_all_samples=int((f.abs()==1).all(-1).sum()),near99_any_samples=int((f.abs()>=.99).any(-1).sum()),near99_all_samples=int((f.abs()>=.99).all(-1).sum()),near999_any_samples=int((f.abs()>=.999).any(-1).sum()),mean_tanh_derivative=float((1-f.double().square()).mean()),preactivation_abs_max=float(pre[:,ix].abs().max()),preactivation_abs_mean=float(pre[:,ix].abs().mean()),beta_mae=float(e.abs().mean()),beta_rmse=float(e.square().mean().sqrt()),beta_bias=float(e.mean()),mass2_beta_mse=float((ww*e.square()).sum()),local_mse=float(localmse[:,ix].mean()));eventrows.append(evrow)
   sm=scales.cpu().numpy();recover=relative.cpu().numpy();nrm=normrms.cpu().numpy();em=err.abs().mean(0).cpu().numpy();wm=(w*err.square()).sum(0).cpu().numpy();lmse=localmse.mean(0).cpu().numpy();slog=np.log(np.maximum(sm,1e-30));bh=bt.cpu().numpy();lh=rt.cpu().numpy();ch=coef.cpu().numpy()
   for p in range(P):
    identity=rawhash[p]+':'+sumhash[p] if p<hp else event+':'+str(p);pg=dict(**meta,page=p,kind='history' if p<hp else 'current',identity=identity,beta_mae=float(em[p]),mass2_beta_mse=float(wm[p]),local_mse=float(lmse[p]),coefficient_beta_norm=float(np.linalg.norm(ch[p,:,16])),coefficient_response_norm=float(np.linalg.norm(ch[p,:,:16])),**{k:bool(v[p]) for k,v in flags.items()})
    for z,name in enumerate(['K','mean','detail','stats']):pg['scale_'+name]=float(sm[p,z]);pg['log_scale_'+name]=float(slog[p,z]);pg['normalized_rms_'+name]=float(nrm[p,z]);pg['scale_reconstruction_relative_'+name]=float(recover[p,z]) if math.isfinite(float(recover[p,z])) else None
    pages.append(pg)
    for typ,peer,dist in [('nearest',int(nn[p]),float(f_dist[p])),('fixed_control',int(control[p]),float(ctrl_dist[p]))]:
     pairs.append(dict(**meta,page=p,peer=peer,kind=typ,feature_distance=dist,log_scale_distance=float(np.linalg.norm(slog[p]-slog[peer])),beta_target_rmse=float(np.mean((bh[:,p]-bh[:,peer])**2)**.5),response_target_rmse=float(np.mean((lh[:,p]-lh[:,peer])**2)**.5),error_difference=float(abs(em[p]-em[peer])),**{'log_scale_diff_'+n:float(abs(slog[p,z]-slog[peer,z])) for z,n in enumerate(['K','mean','detail','stats'])}))
    if p<hp:
     identities[(ev['trajectory'],ev['layer'],ev['head'],rawhash[p],sumhash[p])].append(dict(event=event,page=p));numericids[identity].add((cohash[p],ahash[p]))
   np.savez_compressed(dest/f'event_{idx:04d}.npz',F=F.cpu().numpy(),preactivation=pre.cpu().numpy(),beta=bt.cpu().numpy(),predicted_beta=bp.cpu().numpy(),logmass=lm.cpu().numpy(),local_mse=localmse.cpu().numpy(),q=ev['q'].float().numpy(),**{'role_'+k:v.cpu().numpy() for k,v in flags.items()});sources.append(dict(event=event,event_sha=sha(path),kv_file=str(kvpath.relative_to(OUT)),summary_file=fn.name,summary_sha=sha(fn)))
  if gi%48==0:print('CAPTURE',seed,split,gi,len(groups),round(time.time()-start),flush=True)
 # Numeric coefficient hashes are checked separately from physical identity.
 assert all(torch.equal(v.cpu(),frozen[n]) for n,v in bundle.layers.state_dict().items())
 idrows=[dict(group=list(k[:3]),raw_sha=k[3],summary_sha=k[4],occurrences=v) for k,v in identities.items()];dump(dest/'identities.json',idrows);dump(dest/'metadata.json',sorted(metas,key=lambda x:x['index']));dump(dest/'sources.json',sources);table(dest/'page_scales.csv',pages);table(dest/'similar_page_pairs.csv',pairs);table(dest/'event_roles.csv',eventrows);dump(dest/'capture_complete.json',dict(seed=seed,split=split,events=len(paths),raw_KV_offline_rebuild_authorized=True,raw_attention_recomputed=False,summary_update=False,training=False,test=False,dev_replay_max_beta_error=maxreplay,physical_groups=len(identities),groups_with_different_numeric_coefficients=sum(len(v)>1 for v in numericids.values()),C_sha=sha(checkpoint('C',seed)),reader_sha=sha(E29/f's{seed}/selected.pt'),phi_sha=sha(E27/f's{seed}/selected.pt'),seconds=time.time()-start));print('CAPTURE DONE',seed,split,flush=True)

def analyze_full(seed,split):
 from .cached import analyze
 dest=DEST/f'{split}_s{seed}';assert (dest/'capture_complete.json').exists();meta=json.loads((dest/'metadata.json').read_text());records=[];names={m['event']:i for i,m in enumerate(meta)}
 for m in meta:
  p=np.load(dest/f'event_{m["index"]:04d}.npz');q=p['q'];records.append(dict(meta=m,F=p['F'],beta=p['beta'],bp=p['predicted_beta'],lm=p['logmass'],flags={k[5:]:p[k] for k in p.files if k.startswith('role_')},qh=[hashlib.sha256(z.tobytes()).hexdigest() for z in q],qnorm=np.linalg.norm(q,axis=1),hp=m['history_pages']))
 # Keep capture event-role file intact; analyzer rewrites it using serialized CSV rows.
 with (dest/'event_roles.csv').open() as f:er=list(csv.DictReader(f))
 analyze(seed,dest,json.loads((dest/'identities.json').read_text()),names,records,er,json.loads((dest/'sources.json').read_text()),time.time(),split=split)
 # annotate availability: original cached analyzer had none; this pass does.
 p=dest/'complete.json';x=json.loads(p.read_text());x.update(preactivation_available=True,page_scales_available=True,raw_KV_read=True,raw_KV_use='authorized frozen summary rebuild only');dump(p,x)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--seed',type=int,required=True);p.add_argument('--split',choices=['train','development'],required=True);p.add_argument('--mode',choices=['capture','analyze'],required=True);a=p.parse_args();{'capture':capture,'analyze':analyze_full}[a.mode](a.seed,a.split)
